INSERT INTO "entities" VALUES('ent_ec6faea5524141b688366b9f94801047','Signing in.','2026-10-22T18:23:48.464Z',NULL,NULL,NULL);
INSERT INTO "entities" VALUES('ent_16cd282d2284474a862a86776d3fbaf0','An authenticated visit.','2026-10-22T18:23:48.474Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('contains','Parent → member. Structural composition between long-lived entities (e.g. parent corp → subsidiary, category → member). Same top-down direction as statement links: parent is the source.','2026-10-22T18:23:48.300Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('replaces','Source entity supersedes target entity (e.g. one provider replacing another).','2026-10-22T18:23:48.300Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('sub-type','Source is a specialization of target. Reads ''source is a sub-type of target'' (e.g. Ubeeo is a sub-type of ATS, hard_skill_german_language is a sub-type of Hard Skill). Parent / general category at the target end.','2026-10-22T18:23:48.300Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('has','Source has the target as a component, attribute, or related object. Generic ownership/composition relation between long-lived entities when neither `contains` (strict structural membership) nor `sub-type` (specialization) fits.','2026-10-22T18:23:48.300Z',NULL,NULL,NULL);
INSERT INTO "entity_link_type_glossary" VALUES('uses','Source depends on or makes use of target. Behavioural dependency between long-lived entities — distinct from structural composition (`contains`) and specialization (`sub-type`).','2026-10-22T18:23:48.300Z',NULL,NULL,NULL);
INSERT INTO "entity_links" VALUES('ent_ec6faea5524141b688366b9f94801047','ent_16cd282d2284474a862a86776d3fbaf0','contains','2026-10-22T18:23:48.477Z',NULL);
